package jp.yaegaki.equipment;
import android.content.*;import android.graphics.Bitmap;import java.util.*;import java.util.concurrent.*;import jp.co.kingjim.tepraprint.sdk.*;
public final class Printer {
 public interface Listener{void found(Map<String,String> p);void status(String s);void finished(boolean ok,String message);}
 private final Context ctx;private final Listener listener;private TepraPrintDiscoverPrinter discover;private TepraPrint printer;private final ExecutorService executor=Executors.newSingleThreadExecutor();private boolean busy=false;
 Printer(Context c,Listener l){ctx=c;listener=l;}
 void search(){stopSearch();discover=new TepraPrintDiscoverPrinter(Arrays.asList("_pdl-datastream._tcp.local."),Arrays.asList("(KING JIM TEPRA PRO SR5900P)"),EnumSet.of(TepraPrintDiscoverConnectionType.ConnectionTypeNetwork));discover.setCallback(new TepraPrintDiscoverPrinterCallback(){public void onFindPrinter(TepraPrintDiscoverPrinter d,Map<String,String> p){listener.found(new HashMap<>(p));}public void onRemovePrinter(TepraPrintDiscoverPrinter d,Map<String,String> p){}});discover.startDiscover(ctx);}
 void stopSearch(){if(discover!=null){discover.stopDiscover();discover=null;}}
 static Map<String,String> manual(String ip){Map<String,String> p=new HashMap<>();p.put(TepraPrintDiscoverPrinter.PRINTER_INFO_NAME,"SR5900P");p.put(TepraPrintDiscoverPrinter.PRINTER_INFO_PRODUCT,"(KING JIM TEPRA PRO SR5900P)");p.put(TepraPrintDiscoverPrinter.PRINTER_INFO_USBMDL,"SR5900P");p.put(TepraPrintDiscoverPrinter.PRINTER_INFO_HOST,ip);p.put(TepraPrintDiscoverPrinter.PRINTER_INFO_PORT,"9100");p.put(TepraPrintDiscoverPrinter.PRINTER_INFO_TYPE,"_pdl-datastream._tcp.");p.put(TepraPrintDiscoverPrinter.PRINTER_INFO_DOMAIN,"local.");return p;}
 synchronized void print(Map<String,String> device,List<String> lines,String url,int mm){if(busy){listener.status("印刷処理中です");return;}busy=true;executor.execute(()->{try{printer=new TepraPrint(ctx);printer.setPrinterInformation(device);printer.setCallback(new TepraPrintCallback(){public void onChangePrintOperationPhase(TepraPrint p,int phase){if(phase==TepraPrintPrintingPhase.Complete)end(true,"印刷が完了しました");}public void onSuspendPrintOperation(TepraPrint p,int error,int status){p.cancelPrint();end(false,"印刷停止：接続="+error+" / 本体="+status+"。テープ・カバーを確認してください。");}public void onAbortPrintOperation(TepraPrint p,int error,int status){end(false,"印刷エラー：接続="+error+" / 本体="+status);}public void onChangeTapeFeedOperationPhase(TepraPrint p,int phase){}public void onAbortTapeFeedOperation(TepraPrint p,int error,int status){end(false,"テープ送りエラー："+status);}});
 listener.status("プリンターの状態を確認中…");Map<String,Integer> status=printer.fetchPrinterStatus();if(status==null||status.isEmpty())throw new Exception("SR5900Pと通信できません。同じWi-FiとプリンターのIPを確認してください。");int error=printer.getDeviceErrorFromStatus(status);if(error!=TepraPrintStatusError.NoError)throw new Exception("プリンターの状態を確認してください。エラー="+error);int tape=printer.getTapeWidthFromStatus(status);int expected=mm==12?TepraPrintTapeWidth.Normal_12mm:mm==18?TepraPrintTapeWidth.Normal_18mm:mm==24?TepraPrintTapeWidth.Normal_24mm:TepraPrintTapeWidth.Normal_36mm;if(tape!=expected)throw new Exception("装着されたテープ幅が選択と違います。アプリで実際の幅を選び直してください。");
 Bitmap bitmap=Labels.render(lines,url,printer.getPrintableSizeFromTape(tape),printer.getResolution());Map<String,Object> params=new HashMap<>();params.put(TepraPrintParameterKey.Copies,1);params.put(TepraPrintParameterKey.TapeCut,TepraPrintTapeCut.EachLabel);params.put(TepraPrintParameterKey.HalfCut,printer.isSupportHalfCut());params.put(TepraPrintParameterKey.PrintSpeed,TepraPrintPrintSpeed.PrintSpeedHigh);params.put(TepraPrintParameterKey.Density,0);params.put(TepraPrintParameterKey.TapeWidth,tape);params.put(TepraPrintParameterKey.PriorityPrintSetting,false);params.put(TepraPrintParameterKey.HalfCutContinuous,false);listener.status("印刷データを送信中…");printer.doPrint(bitmap,params);
 }catch(Exception|LinkageError e){end(false,e.getMessage()==null?"印刷モジュールを起動できません":e.getMessage());}});}
 private synchronized void end(boolean ok,String message){if(!busy)return;busy=false;listener.finished(ok,message);}
 void cancel(){executor.execute(()->{if(printer!=null)printer.cancelPrint();end(false,"印刷を中止しました");});}
}
